def _sentence_end(chunk):
    # Equivalent of CPython's _sentence_end_re: [a-z][.!?]["']?\Z
    n = len(chunk)
    if n >= 2 and "a" <= chunk[-2] <= "z" and chunk[-1] in ".!?":
        return True
    return n >= 3 and "a" <= chunk[-3] <= "z" and chunk[-2] in ".!?" and chunk[-1] in "\"'"


